  /// one's clothes.
  @ffi.Uint32()
  external int color;

  /// How far from the key colour still counts as background, as a **fraction
  /// of the way from that colour to grey**: 0 removes only the colour itself
  /// and is what a zeroed struct says, 1 removes everything that leans that way
  /// at all. See the head of this file for why it is a fraction rather than a
  /// distance.
  ///
  /// This is the on switch as well as the amount. A separate `enabled` flag
  /// would be a second thing that can disagree with it, and a document that
  /// records what *happens* has no room for the difference between a key
  /// turned off and a key set to remove nothing.
  @ffi.Float()
  external double tolerance;

  /// The width of the ramp from gone to kept, measured outwards from
  /// `tolerance` in the same fractions. 0 is a hard edge.
  ///
  /// Smoothstepped rather than linear: a linear ramp leaves a corner where the
  /// matte meets solid, and that corner reads as a bright line drawn around
  /// the subject — the one artefact everybody recognises as a bad key.
  @ffi.Float()
  external double softness;

  /// How much of the key's own colour to pull out of what is left: 0 leaves
  /// the fringe as it was shot, 1 takes all of it.
  ///
  /// Green bounces off a screen onto everything in front of it, so the edge of
  /// a subject is green even where it is opaque. The removal happens along the
  /// same chroma axis the matte is measured on — one space paying for both
  /// halves of the feature — and **at constant luma**, which is the whole
  /// trick: taking green off the green *channel* darkens every edge pixel it
  /// touches and trades a green halo for a grey one. See `vd_key_apply`.
  @ffi.Float()
  external double spill;
}

/// A colour's position in the chroma plane: how far it is from grey, and in
/// which direction. Grey is {0, 0}.
///
/// BT.709, whatever matrix the source was coded in — see the head of this file.
final class VdChroma extends ffi.Struct {
  @ffi.Float()
  external double cb;

  @ffi.Float()
  external double cr;
}

/// The key resolved into what the shader actually needs: the chroma point to
/// measure from, the unit vector to despill along, and the two thresholds.
///
/// Worked out once per layer on the CPU rather than once per fragment on the
/// GPU — the same division of labour `vd_color_transform` makes, for the same
/// reason: the part that decides what the control *means* is the part worth
/// testing, and a normalise per pixel is a normalise of a constant.
final class VdKeyMatte extends ffi.Struct {
  /// The key colour's chroma divided by its own luma: where it sits once its
  /// brightness has been taken out. Distances are measured from here, against
  /// pixels treated the same way.
  external VdChroma chromaticity;

  /// `chromaticity` normalised: the axis a despill subtracts along. {0, 0} when
  /// the key is grey, which is one of the two ways a key is off.
  external VdChroma axis;

  /// One over the length of `chromaticity`, which is what turns a distance into
  /// a fraction of the way from the key colour to grey — so `tolerance` means
  /// the same thing on a blue screen as on a green one.
  @ffi.Float()
  external double inv_length;

  @ffi.Float()
  external double tolerance;

  @ffi.Float()
  external double softness;

  @ffi.Float()
  external double spill;
}

/// The presets, in the order a picker offers them.
///
/// One direction each. `VD_TRANSITION_WIPE` wipes left to right and
/// `VD_TRANSITION_SLIDE` brings the new clip in from the right, because a
/// picker with four arrows per entry is a picker with twenty entries — and the
/// enum may be appended to, so the other directions can arrive as their own
/// presets the way `VD_ANIM_SLIDE_*` did.
///
/// Values cross the FFI boundary as integers: append only, never reorder.
enum VdTransitionPreset {
  VD_TRANSITION_NONE(0),

  /// The new clip fades up over the old one. The one that suits anything.
  VD_TRANSITION_DISSOLVE(1),

  /// Down to a colour and back up out of it. Black and white are two presets
  /// rather than a preset and a colour, because these two are the ones anybody
  /// asks for and a colour well would be a whole control for the third.
  VD_TRANSITION_FADE_BLACK(2),
  VD_TRANSITION_FADE_WHITE(3),

  /// The new clip slides in from the right over the old one, which stays put.
  VD_TRANSITION_SLIDE(4),

  /// The same slide, but the old clip is shoved out of the frame by it.
  VD_TRANSITION_PUSH(5),

  /// A hard edge travelling left to right, the new clip behind it.
  VD_TRANSITION_WIPE(6);

  final int value;
  const VdTransitionPreset(this.value);

  static VdTransitionPreset fromValue(int value) => switch (value) {
    0 => VD_TRANSITION_NONE,
    1 => VD_TRANSITION_DISSOLVE,
    2 => VD_TRANSITION_FADE_BLACK,
    3 => VD_TRANSITION_FADE_WHITE,
    4 => VD_TRANSITION_SLIDE,
    5 => VD_TRANSITION_PUSH,
    6 => VD_TRANSITION_WIPE,
    _ => throw ArgumentError('Unknown value for VdTransitionPreset: $value'),
  };
}

/// What the two clips look like at one instant.
///
/// "Out" is the clip leaving and "in" is the clip arriving. Offsets are
/// fractions of the output's width and height, the same units `VdTransform`
/// uses, and they are *added* to whatever transform the clip already had — a
/// clip someone pushed to one side still pushes out from where they put it.
final class VdTransitionValue extends ffi.Struct {
  @ffi.Float()
  external double out_opacity;

  @ffi.Float()
  external double in_opacity;

  @ffi.Float()
  external double out_offset_x;

  @ffi.Float()
  external double out_offset_y;

  @ffi.Float()
  external double in_offset_x;

  @ffi.Float()
  external double in_offset_y;

  /// How much of the incoming clip to cut away from each side, as fractions of
  /// its own rectangle. Zeroed cuts nothing away. This is the one thing a
  /// transition needs that a transform cannot express: a wipe is a hard edge
  /// moving across a picture that is standing still, not a picture moving.
  @ffi.Float()
  external double in_hide_left;

  @ffi.Float()
  external double in_hide_top;

  @ffi.Float()
  external double in_hide_right;

  @ffi.Float()
  external double in_hide_bottom;

  /// A solid colour laid over *both* clips, and how opaque it is. 0 draws
  /// nothing, which is every preset but the two fades.
  ///
  /// A layer of its own, laid over the two clips at the cut and under anything
  /// on a higher track — a caption over a fade-to-black stays legible, which is
  /// what makes it a transition between two clips rather than an effect on the
  /// whole frame.
  ///
  /// It has to be a layer. Turning the two clips' own opacity down instead
  /// dips to whatever is *behind* them: black on the main track, which looks
  /// right by accident, and the main track's picture on an overlay lane, which
  /// does not. And there is no opacity at all that fades a clip to white.
  @ffi.Float()
  external double flash;

  /// 0xAARRGGBB
  @ffi.Uint32()
  external int flash_color;
}

/// The transition at the head of one clip.
final class VdClipTransition extends ffi.Struct {
  @ffi.UnsignedInt()
  external int presetAsInt;

  VdTransitionPreset get preset => VdTransitionPreset.fromValue(presetAsInt);

  /// The whole window, half of it either side of the cut. 0 is no transition,
  /// whatever the preset says.
  @VdTick()
  external int duration;
}

enum VdResult {
  VD_OK(0),

  /// could not open the file at all
  VD_ERR_OPEN(-1),

  /// opened, but nothing playable inside
  VD_ERR_NO_STREAMS(-2),
  VD_ERR_INVALID_ARG(-3),
  VD_ERR_UNSUPPORTED(-4),

  /// opened, but a frame could not be produced
  VD_ERR_DECODE(-5);

  final int value;
  const VdResult(this.value);

  static VdResult fromValue(int value) => switch (value) {
    0 => VD_OK,
    -1 => VD_ERR_OPEN,
    -2 => VD_ERR_NO_STREAMS,
    -3 => VD_ERR_INVALID_ARG,
    -4 => VD_ERR_UNSUPPORTED,
    -5 => VD_ERR_DECODE,
    _ => throw ArgumentError('Unknown value for VdResult: $value'),
  };
}

final class VdProbeInfo extends ffi.Struct {
  @ffi.Bool()
  external bool has_video;

  @ffi.Bool()
  external bool has_audio;

  /// Duration of the longest stream, in project ticks. 0 when the container
  /// does not say — a stream, or a damaged file.
  @VdTick()
  external int duration;

  /// Coded dimensions, before rotation.
  @ffi.Int32()
  external int width;

  @ffi.Int32()
  external int height;

  /// Display rotation from the container: 0, 90, 180 or 270.
  @ffi.Int32()
  external int rotation_degrees;

  /// Nominal frame rate. When `variable_frame_rate` is set this is the average,
  /// and individual frames will not land on it — they are normalised to the
  /// project timebase at decode time.
  external VdRational frame_rate;

  @ffi.Bool()
  external bool variable_frame_rate;

  @ffi.Int32()
  external int audio_channels;

  @ffi.Int32()
  external int audio_sample_rate;

  /// Sample aspect ratio; {1,1} for square pixels.
  external VdRational pixel_aspect;

  @ffi.Array.multi([32])
  external ffi.Array<ffi.Char> video_codec;

  @ffi.Array.multi([32])
  external ffi.Array<ffi.Char> audio_codec;

  @ffi.Array.multi([64])
  external ffi.Array<ffi.Char> format_name;
}

final class VdDecoder extends ffi.Opaque {}

enum VdPixelFormat {
  /// Zero-copy from VideoToolbox: an IOSurface-backed NV12 buffer, ready for
  /// the Metal compositor to sample directly.
  VD_PIXEL_NV12(0),

  /// Software decode, copied into a planar buffer. Slower, and the compositor
  /// has to sample it differently.
  VD_PIXEL_YUV420P(1),

  /// Not something a decoder produces: premultiplied BGRA, which is what a
  /// generated layer — a caption, a shape — arrives as. It lives in this enum
  /// rather than in one of its own because VdLayer::format is the only thing
  /// that reads it, and the compositor should not have to be told twice what
  /// kind of pixels it is being handed.
  VD_PIXEL_BGRA(2);

  final int value;
  const VdPixelFormat(this.value);

  static VdPixelFormat fromValue(int value) => switch (value) {
    0 => VD_PIXEL_NV12,
    1 => VD_PIXEL_YUV420P,
    2 => VD_PIXEL_BGRA,
    _ => throw ArgumentError('Unknown value for VdPixelFormat: $value'),
  };
}

final class VdDecoderOptions extends ffi.Struct {
  /// 1 to try VideoToolbox. Falls back to software if the codec cannot be
  /// hardware-decoded; check VdFrame::hardware to see what actually happened.
  @ffi.Int32()
  external int hardware;

  /// Decoded frames to retain. 0 picks a default sized for scrubbing back and
  /// forth across a second or so of footage.
  @ffi.Int32()
  external int cache_capacity;
}

/// The YCbCr matrix a source was encoded with. Getting this wrong does not
/// look broken, it looks *slightly off* — which is worse, because nobody
/// reports it and every export inherits it.
enum VdColorMatrix {
  VD_MATRIX_BT601(0),
  VD_MATRIX_BT709(1),
  VD_MATRIX_BT2020(2);

  final int value;
  const VdColorMatrix(this.value);

  static VdColorMatrix fromValue(int value) => switch (value) {
    0 => VD_MATRIX_BT601,
    1 => VD_MATRIX_BT709,
    2 => VD_MATRIX_BT2020,
    _ => throw ArgumentError('Unknown value for VdColorMatrix: $value'),
  };
}

final class VdFrame extends ffi.Struct {
  /// CVPixelBufferRef, retained. Release with vd_frame_release, always, on
  /// every path — the cache holds its own reference and does not care about
  /// yours.
  external ffi.Pointer<ffi.Void> pixel_buffer;

  @ffi.UnsignedInt()
  external int formatAsInt;

  VdPixelFormat get format => VdPixelFormat.fromValue(formatAsInt);

  /// The presentation interval this frame covers: [pts, pts + duration).
  ///
  /// `duration` runs to the presentation time of the frame that follows, which
  /// is not always what the container claims — muxers write per-frame durations
  /// in decode order, so with B-frames they land on the wrong frames, and on a
  /// variable-rate source the difference is frames from the future rather than
  /// a rounding error. The last frame of a source is the exception: nothing
  /// follows it, so it carries the nominal duration and queries past it clamp.
  @VdTick()
  external int pts;

  @VdTick()
  external int duration;

  @ffi.Int32()
  external int width;

  @ffi.Int32()
  external int height;

  @ffi.Bool()
  external bool hardware;

  @ffi.UnsignedInt()
  external int color_matrixAsInt;

  VdColorMatrix get color_matrix => VdColorMatrix.fromValue(color_matrixAsInt);

  /// True for 0-255 luma, false for the 16-235 video range most sources use.
  @ffi.Bool()
  external bool full_range;
}

/// --- telemetry -------------------------------------------------------------
final class VdDecoderStats extends ffi.Struct {
  @ffi.Int64()
  external int frames_decoded;

  @ffi.Int64()
  external int cache_hits;

  @ffi.Int64()
  external int cache_misses;

  @ffi.Int64()
  external int seeks;

  @ffi.Int64()
  external int decode_errors;
}

final class VdCompositor extends ffi.Opaque {}

/// How a source that does not match the output aspect is placed.
enum VdFitMode {
  /// whole frame visible, letterboxed
  VD_FIT_CONTAIN(0),

  /// fills the output, edges cropped
  VD_FIT_COVER(1),

  /// ignores aspect
  VD_FIT_STRETCH(2),

  /// Whole frame visible, and the bars filled with a blurred, cover-fitted
  /// copy of the same picture rather than black. Costs three extra passes, and
  /// only when there are bars to fill — a clip that already fills the output
  /// takes the ordinary path.
  VD_FIT_BLUR(3);

  final int value;
  const VdFitMode(this.value);

  static VdFitMode fromValue(int value) => switch (value) {
    0 => VD_FIT_CONTAIN,
    1 => VD_FIT_COVER,
    2 => VD_FIT_STRETCH,
    3 => VD_FIT_BLUR,
    _ => throw ArgumentError('Unknown value for VdFitMode: $value'),
  };
}

/// What a clip does to itself before it is composited: where it sits, how big
/// it is, which way up, and how much of it shows.
///
/// Every field is defined so that **a zeroed struct is the identity**. A caller
/// that does not care about transforms can `memset` its layers and never learn
/// this field exists, which is worth more than the two lines it costs to treat
/// a zero scale as one.
///
/// Applied in this order, about the layer's own centre: crop, then the fit the
/// mode asked for, then scale, then rotation, then offset. Crop first because
/// cropping changes the aspect ratio, and a fit computed before it would letter
/// box the part that was thrown away.
final class VdTransform extends ffi.Struct {
  /// Offset from the centre of the output, as a fraction of the output's own
  /// width and height. {0,0} is centred; {0.5,0} is off the right edge.
  @ffi.Float()
  external double offset_x;

  @ffi.Float()
  external double offset_y;

  /// Uniform multiplier on the fitted size. 0 and 1 both mean "as fitted".
  @ffi.Float()
  external double scale;

  /// Extra clockwise rotation in degrees, on top of whatever the source's own
  /// orientation metadata already asked for. Any angle, not just quarter turns.
  @ffi.Float()
  external double rotation_degrees;

  /// The part of the *display-oriented* source to show, normalised, origin top
  /// left. A zeroed width or height means the whole thing.
  @ffi.Float()
  external double crop_x;

  @ffi.Float()
  external double crop_y;

  @ffi.Float()
  external double crop_w;

  @ffi.Float()
  external double crop_h;

  /// Mirrored horizontally / vertically, in display orientation.
  @ffi.Bool()
  external bool flip_h;

  @ffi.Bool()
  external bool flip_v;
}

/// How much of a layer to cut away from each side, as fractions of its own
/// rectangle. Zeroed cuts nothing away — see VdLayer::reveal.
final class VdReveal extends ffi.Struct {
  @ffi.Float()
  external double left;

  @ffi.Float()
  external double top;

  @ffi.Float()
  external double right;

  @ffi.Float()
  external double bottom;
}

final class VdLayer extends ffi.Struct {
  /// CVPixelBufferRef from vd_decoder_frame_at. Borrowed for the duration of
  /// the call; the compositor does not retain it.
  external ffi.Pointer<ffi.Void> pixel_buffer;

  @ffi.UnsignedInt()
  external int formatAsInt;

  VdPixelFormat get format => VdPixelFormat.fromValue(formatAsInt);

  /// Clockwise degrees to rotate for display: 0, 90, 180, 270.
  @ffi.Int32()
  external int rotation_degrees;

  /// The source's sample aspect: how much wider one of its pixels is than it
  /// is tall. {0,0} and {1,1} both mean square, so a caller with square pixels
  /// can leave it zeroed. Applied before the rotation, because a turn swaps
  /// which axis the stretch is on.
  ///
  /// This is what makes a 4:3 DVD frame stored as 720x480 come out 4:3 rather
  /// than squeezed to 3:2. It belongs on the layer rather than being folded
  /// into the coded size by the decoder, because the pixels really are 720
  /// across — only the shape they are meant to be shown at differs.
  external VdRational pixel_aspect;

  /// Copied straight from the VdFrame the buffer came out of.
  @ffi.UnsignedInt()
  external int color_matrixAsInt;

  VdColorMatrix get color_matrix => VdColorMatrix.fromValue(color_matrixAsInt);

  @ffi.Bool()
  external bool full_range;

  @ffi.UnsignedInt()
  external int fitAsInt;

  VdFitMode get fit => VdFitMode.fromValue(fitAsInt);

  /// 0..1
  @ffi.Float()
  external double opacity;

  /// How much of the layer to cut away from each side, as fractions of its own
  /// rectangle. A zeroed value cuts nothing away, so a caller with nothing to
  /// say about it can leave the field alone.
  ///
  /// A hard edge rather than a fade, and in the layer's *own* space rather than
  /// the output's, so it travels with the clip if the clip is also moving. This
  /// is the one thing a transition needs that a transform cannot express: a
  /// wipe is an edge crossing a picture that is standing still, where a crop
  /// would shrink the picture and a scale would move it.
  external VdReveal reveal;

  /// Where this layer goes and how much of it shows. A zeroed transform is the
  /// identity, so this may be ignored entirely.
  external VdTransform transform;

  /// What this layer does to its own colour: brightness, contrast, saturation,
  /// temperature, tint. A zeroed value is the neutral grade, so this is another
  /// field a caller can leave alone — see vd_color.h.
  ///
  /// Per layer rather than per frame, and that is the decision. A grade on the
  /// frame would be an effect on the *project*, which is a different feature
  /// and a worse one to have by accident: a shot that needed warming would warm
  /// the caption over it and the shot on the lane beneath it too. Here it
  /// travels with the clip, the way its opacity and its transform do, and a
  /// blur-filled clip's backdrop is graded with it because the backdrop is the
  /// same picture.
  external VdColorAdjust color;

  /// The other half of the same grade: the part that cannot be a matrix. A
  /// zeroed value is no look, so this is a field a caller can leave alone.
  ///
  /// The lattice is borrowed for the duration of the call, like `pixel_buffer`
  /// — but unlike a pixel buffer it is uploaded to the GPU and *kept*, keyed on
  /// `id`, because a look is the same cube on every frame of every clip wearing
  /// it. See vd_compositor_lut_uploads for how that is asserted.
  ///
  /// Applied after `color`, which is the order a colourist works in: correct
  /// the shot, then style it. See vd_lut.h.
  external VdColorLook look;

  /// What this layer removes from itself. A zeroed VdChromaKey removes nothing,
  /// so this is another field a caller can leave alone — see vd_key.h.
  ///
  /// Applied **before** `color` and `look`, and that is the decision. A key
  /// measured on a graded picture makes every slider in the colour panel above
  /// it secretly a keying control: turn up the contrast and the matte closes
  /// over. The despill runs there too, so what the grade is handed is a
  /// corrected plate.
  ///
  /// **A keyed layer is contained, whatever `fit` says.** A blur fill paints
  /// the bars with a blurred copy of this same picture, and filling them with a
  /// copy of a background the user has just declared is not there is a
  /// contradiction — it floods the frame with the very colour being removed.
  /// Worse, the backdrop is rendered into an offscreen cleared to opaque black
  /// and then drawn full-frame, so the holes a key put in it would paint black
  /// over every layer underneath. VD_FIT_BLUR therefore reads as
  /// VD_FIT_CONTAIN here. A rendering rule and not a document change: nothing
  /// rewrites the fit the user chose.
  external VdChromaKey key;

  /// Draws this layer's alpha as luminance instead of its picture — white where
  /// it reaches the frame, black where it does not — which is how somebody
  /// sees what a tolerance is actually doing.
  ///
  /// It is a property of the person looking rather than of the document, so
  /// nothing on a clip carries it: `vd_engine_set_view` sets it on every layer
  /// at once, and vd_export builds its own engine that never calls that. See
  /// VdViewMode in vd_engine.h for why it lives there and not in the render
  /// list.
  ///
  /// Opaque, so the black paints over what is underneath rather than letting it
  /// show through a hole — a matte you can see past is not a matte. And it is
  /// the alpha *after* opacity, because the question it answers is how much of
  /// this layer reaches the frame.
  @ffi.Bool()
  external bool matte_view;
}

/// What gets drawn inside the box.
///
/// **One box, four shapes.** Every kind is drawn inside the same rectangle —
/// `width` by `height`, centred in the frame — which is what makes the two size
/// numbers mean the same thing in all of them. A rectangle fills the box, an
/// ellipse is inscribed in it, and a line runs across it from the middle of the
/// left edge to the middle of the right.
///
/// A rounded rectangle is `VD_SHAPE_RECT` with a `corner`, and a circle is
/// `VD_SHAPE_ELLIPSE` with equal sides, rather than kinds of their own: both
/// are one slider away from the shape beside them, and a picker with six
/// entries where four would do makes the reader look for a difference that is
/// not there.
///
/// Values cross the FFI boundary as integers, so these may be appended to and
/// never reordered.
enum VdShapeKind {
  VD_SHAPE_RECT(0),
  VD_SHAPE_ELLIPSE(1),

  /// The stroke *is* the shape: a line has no interior, so `fill_color` says
  /// nothing about it and a line with no stroke width draws nothing — the same
  /// rule a rectangle with no fill already follows.
  VD_SHAPE_LINE(2),

  /// A line with a head on its right end. Right, because that is the direction
  /// the clip's own rotation turns towards, so "which way does it point" has
  /// one answer and it is the transform's.
  VD_SHAPE_ARROW(3);

  final int value;
  const VdShapeKind(this.value);

  static VdShapeKind fromValue(int value) => switch (value) {
    0 => VD_SHAPE_RECT,
    1 => VD_SHAPE_ELLIPSE,
    2 => VD_SHAPE_LINE,
    3 => VD_SHAPE_ARROW,
    _ => throw ArgumentError('Unknown value for VdShapeKind: $value'),
  };
}

/// Everything about how one shape looks.
///
/// All scalars, unlike VdTextSpec — there is no string in a rectangle — which
/// is why the copy below is a memcpy and the comparison is worth reading.
///
/// Colours are 0xAARRGGBB, straight (not premultiplied). Alpha 0 means *off*:
/// a fill with no alpha draws no fill, a stroke with none draws no outline, a
/// shadow colour with none casts no shadow. One rule rather than three booleans
/// nobody would keep in step with the colours beside them.
final class VdShapeSpec extends ffi.Struct {
  @ffi.UnsignedInt()
  external int kindAsInt;

  VdShapeKind get kind => VdShapeKind.fromValue(kindAsInt);

  /// The box, as fractions of the output height. Equal values are a square —
  /// and so a circle, for an ellipse — in a 16:9 project and in a 9:16 one.
  @ffi.Float()
  external double width;

  @ffi.Float()
  external double height;

  /// How round the corners of a rectangle are: 0 is square, 1 is as round as
  /// the box allows, which is a pill on an oblong and a circle on a square. A
  /// proportion rather than a length, so a rectangle keeps its corners when it
  /// is resized. Ignored by every kind but VD_SHAPE_RECT.
  @ffi.Float()
  external double corner;

  /// Ignored by VD_SHAPE_LINE and VD_SHAPE_ARROW, which have no interior.
  @ffi.Uint32()
  external int fill_color;

  /// Drawn over the fill, straddling the edge, which is what every drawing
  /// program does and what keeps a filled shape the size it says it is.
  @ffi.Uint32()
  external int stroke_color;

  @ffi.Float()
  external double stroke_width;

  /// Cast by the whole shape — fill and stroke together, as one silhouette —
  /// onto whatever is behind it. +y is down, the direction a light above the
  /// frame throws it.
  @ffi.Uint32()
  external int shadow_color;

  @ffi.Float()
  external double shadow_dx;

  @ffi.Float()
  external double shadow_dy;

  @ffi.Float()
  external double shadow_blur;

  /// How much of an arrow is head, as a fraction of its length. A proportion
  /// for the same reason `corner` is one: an arrow that is lengthened should
  /// still look like an arrow. Ignored by every kind but VD_SHAPE_ARROW.
  @ffi.Float()
  external double head_size;
}

final class VdSticker extends ffi.Opaque {}

final class VdStickerOptions extends ffi.Struct {
  /// How much decoded RGBA one sticker may hold. 0 picks the default.
  ///
  /// A budget rather than a frame limit, and it *scales* rather than truncates:
  /// an animation too big to hold is decoded smaller, never shorter. Losing
  /// resolution on an overlay is a compromise somebody might not notice; losing
  /// the second half of the animation is a bug they certainly would.
  @ffi.Int64()
  external int max_bytes;

  /// Longest side, in pixels, or 0 for no limit. The engine passes the
  /// output's, because a sticker with more pixels than the frame it is drawn
  /// into is paying for detail the compositor is about to throw away.
  @ffi.Int32()
  external int max_side;
}

/// Where each line sits inside the text block. The block itself is centred in
/// the frame and moved by the clip's transform; this only decides what happens
/// to a short line next to a long one.
enum VdTextAlign {
  VD_TEXT_ALIGN_LEFT(0),
  VD_TEXT_ALIGN_CENTER(1),
  VD_TEXT_ALIGN_RIGHT(2);

  final int value;
  const VdTextAlign(this.value);

  static VdTextAlign fromValue(int value) => switch (value) {
    0 => VD_TEXT_ALIGN_LEFT,
    1 => VD_TEXT_ALIGN_CENTER,
    2 => VD_TEXT_ALIGN_RIGHT,
    _ => throw ArgumentError('Unknown value for VdTextAlign: $value'),
  };
}

/// Everything about how one caption looks.
///
/// Colours are 0xAARRGGBB, straight (not premultiplied) — the document writes
/// them and a human reads them, and premultiplied colour is neither. Alpha 0
/// means *off* for the two optional parts: a shadow colour with no alpha casts
/// no shadow, a box colour with no alpha draws no box. That is one rule rather
/// than two booleans nobody would keep in step with the colours beside them.
final class VdTextSpec extends ffi.Struct {
  /// UTF-8, NUL terminated. NULL or empty renders a transparent frame, which
  /// is what a caption someone has not typed into yet should look like.
  external ffi.Pointer<ffi.Char> text;

  /// Family name as the font file reports it — "Inter", "Playfair Display".
  /// NULL, empty, or a family nothing was registered under falls back to the
  /// system's own, so a project made on a machine with a pack installed still
  /// opens somewhere it is not.
  external ffi.Pointer<ffi.Char> font;

  /// Cap height of the type as a fraction of the output height. 0.08 is a
  /// readable caption on a 16:9 frame.
  @ffi.Float()
  external double size;

  @ffi.Uint32()
  external int color;

  /// An outline, drawn under the fill so only its outer half shows. Width is a
  /// fraction of the font size, which is also how CoreText expresses it.
  @ffi.Uint32()
  external int stroke_color;

  @ffi.Float()
  external double stroke_width;

  /// Cast by the ink — the fill and its outline together — onto whatever is
  /// behind it, including the box. Offsets and blur are fractions of the font
  /// size; +y is down, the direction a light above the frame throws it.
  @ffi.Uint32()
  external int shadow_color;

  @ffi.Float()
  external double shadow_dx;

  @ffi.Float()
  external double shadow_dy;

  @ffi.Float()
  external double shadow_blur;

  /// A rounded rectangle behind the whole block, inset by `box_padding` on
  /// every side. Padding and corner radius are fractions of the font size, so
  /// the box keeps its proportions as the type grows.
  @ffi.Uint32()
  external int box_color;

  @ffi.Float()
  external double box_padding;

  @ffi.Float()
  external double box_radius;

  /// Extra space between glyphs, as a fraction of the font size. Negative
  /// tightens.
  @ffi.Float()
  external double letter_spacing;

  /// Multiple of the font's own line height. 0 and 1 both mean "as the font
  /// asked for".
  @ffi.Float()
  external double line_spacing;

  /// How much of the output's width the block may fill before it wraps, as a
  /// fraction. 0 means the default, which leaves a margin — text that touches
  /// the edge of the frame reads as a mistake.
  @ffi.Float()
  external double max_width;

  @ffi.UnsignedInt()
  external int alignAsInt;

  VdTextAlign get align => VdTextAlign.fromValue(alignAsInt);
}

final class VdEngine extends ffi.Opaque {}

final class VdAudioRenderer extends ffi.Opaque {}

enum VdPlaybackState {
  VD_STATE_IDLE(0),
  VD_STATE_PLAYING(1),
  VD_STATE_PAUSED(2),
  VD_STATE_ENDED(3);

  final int value;
  const VdPlaybackState(this.value);

  static VdPlaybackState fromValue(int value) => switch (value) {
    0 => VD_STATE_IDLE,
    1 => VD_STATE_PLAYING,
    2 => VD_STATE_PAUSED,
    3 => VD_STATE_ENDED,
    _ => throw ArgumentError('Unknown value for VdPlaybackState: $value'),
  };
}

/// The shape a fade ramps in. Four of them, each with a job:
///
/// VD_FADE_LINEAR       a straight line in amplitude. The handle position
/// means what it looks like it means, and it is what
/// every project written before this existed has.
/// VD_FADE_SMOOTH       a raised cosine: no corner at either end, which is
/// what a fade over music or a held shot wants.
/// VD_FADE_EQUAL_POWER  a quarter of a sine, which holds *power* constant.
/// Two clips overlapping on two lanes cross through it
/// without the 3 dB dip a pair of linear ramps leaves in
/// the middle — the one shape that is about a crossfade
/// rather than about a fade.
/// VD_FADE_EXPONENTIAL  t squared: starts almost silent and arrives late,
/// which is the shape a long musical fade-in wants.
///
/// One curve per clip rather than one per fade: two shapes on one clip is a
/// distinction nobody makes, and it would double the field, the picker, the
/// file format and the table for nothing.
///
/// Mirrored by `FadeCurve` in app/lib/model/clip.dart and `EngineFadeCurve` in
/// the plugin. The index crosses the FFI boundary, so append only. Zero is
/// linear, which is what makes this a field a caller may leave at whatever a
/// memset gave it.
enum VdFadeCurve {
  VD_FADE_LINEAR(0),
  VD_FADE_SMOOTH(1),
  VD_FADE_EQUAL_POWER(2),
  VD_FADE_EXPONENTIAL(3);

  final int value;
  const VdFadeCurve(this.value);

  static VdFadeCurve fromValue(int value) => switch (value) {
    0 => VD_FADE_LINEAR,
    1 => VD_FADE_SMOOTH,
    2 => VD_FADE_EQUAL_POWER,
    3 => VD_FADE_EXPONENTIAL,
    _ => throw ArgumentError('Unknown value for VdFadeCurve: $value'),
  };
}

/// One point on a clip's volume line.
///
/// `source_time` is in the source's own time — the same coordinate as
/// `source_in` — rather than an offset into the clip, so that trimming a clip
/// slides the window over the automation instead of dragging the automation
/// along with it. A duck stays on the word it was drawn for.
final class VdVolumePoint extends ffi.Struct {
  @VdTick()
  external int source_time;

  @ffi.Float()
  external double value;
}

final class VdTimelineClip extends ffi.Struct {
  /// Absolute path to the source file, or NULL for a clip that generates its
  /// own picture — see `text` and `shape`. Copied on set_timeline; the caller
  /// keeps ownership of its own string.
  external ffi.Pointer<ffi.Char> path;

  /// A caption instead of a file. NULL for every clip that has a `path`, and
  /// the three are exclusive: a clip is a window onto a source, or it is one of
  /// the two things the engine draws, and never two of them at once.
  ///
  /// The spec is copied on set_timeline, strings and all, and the raster it
  /// produces is kept for as long as the clip's spec is unchanged — the same
  /// bargain `path` gets with its decoder, and for the same reason: nudging a
  /// clip must not cost a re-layout of every caption on the timeline.
  external ffi.Pointer<VdTextSpec> text;

  /// A rectangle, an ellipse, a line or an arrow instead of a file. Copied and
  /// cached on exactly the terms `text` is: a shape whose spec did not change
  /// keeps the pixels it already had. See vd_shape.h.
  external ffi.Pointer<VdShapeSpec> shape;

  /// True when `path` is an animated overlay — a GIF, an animated WebP, an
  /// APNG — rather than video. It is decoded whole and looped instead of being
  /// seeked in, which is a different enough thing to be a different module: see
  /// vd_sticker.h.
  ///
  /// The caller is told to say rather than the engine probing to find out, for
  /// the same reason `has_video` is: the document already knows, and a sticker
  /// should not cost a file open on every edit to establish what it is.
  @ffi.Bool()
  external bool sticker;

  /// position on the timeline
  @VdTick()
  external int start;

  /// length on the timeline
  @VdTick()
  external int duration;

  /// offset into the source
  @VdTick()
  external int source_in;

  /// Source seconds per timeline second: 2 plays twice as fast, 0.5 half as
  /// fast, and 1 is every clip nobody retimed. Clamped to [0.1, 10]; zero and
  /// anything negative are read as 1, which is what makes `speed` the one field
  /// on this struct a caller may leave at whatever a memset gave it.
  ///
  /// `duration` is still the clip's length *on the timeline*, so this says
  /// nothing about where the clip sits or how long it lasts — only how fast the
  /// window over the source travels while it is on screen. The source window it
  /// implies is `duration * speed`, and the document is the one that decides
  /// both: retiming a clip is a change of length, not something the engine can
  /// work out on its own.
  @ffi.Double()
  external double speed;

  /// True when a retimed clip should sound like a tape played fast: everything
  /// in it rises in pitch together. False — the default, and what a memset
  /// gives — keeps the pitch it was recorded at and stretches time instead.
  ///
  /// A toggle rather than a rule, because both are right: a slow-motion shot
  /// usually wants the voice in it to still be that voice, and a comedy speed-up
  /// usually wants the chipmunk. Ignored at `speed` 1, where the two agree.
  /// See vd_stretch.h.
  @ffi.Bool()
  external bool pitch_shift;

  /// Compositing order: lower renders first, so 0 is the main track.
  @ffi.Int32()
  external int track;

  @ffi.Float()
  external double opacity;

  @ffi.UnsignedInt()
  external int fitAsInt;

  VdFitMode get fit => VdFitMode.fromValue(fitAsInt);

  /// Where this clip sits inside the frame. A zeroed transform is the identity,
  /// so a caller with nothing to say about it can leave the field alone.
  external VdTransform transform;

  /// What it does to its own colour. A zeroed VdColorAdjust is the neutral
  /// grade, so this is another field a caller can ignore.
  ///
  /// Handed to the compositor untouched, unlike the animation and the
  /// transition beside it: those are functions of *time* and have to be
  /// evaluated per frame, where a grade is the same five numbers at every
  /// instant of the clip. Nothing about it belongs in the render loop, which is
  /// why it is composed into a matrix down in the compositor and not here.
  /// See vd_color.h.
  external VdColorAdjust color;

  /// The look on this clip: a name registered with vd_lut_register, or NULL for
  /// a clip nobody put one on. Copied on set_timeline; the caller keeps
  /// ownership of its own string.
  ///
  /// A name rather than a path or a lattice, exactly as `VdTextSpec::font` is a
  /// family name: the looks the app ships have no path inside a signed bundle,
  /// and a document that names one reads like the edit that made it rather than
  /// like one machine's filesystem. A name nothing was registered under draws
  /// ungraded, which is the bargain a caption in a missing face already takes.
  external ffi.Pointer<ffi.Char> look;

  /// 0..1: how far towards the look to go. Only read when `look` names one.
  @ffi.Float()
  external double look_strength;

  /// What this clip removes from itself: a colour, and how much of it. A zeroed
  /// VdChromaKey removes nothing, so this is a field a caller can ignore.
  ///
  /// Handed to the compositor untouched, like `color` beside it and unlike the
  /// animation and the transition below: a key is the same four numbers at
  /// every instant of the clip, so nothing about it belongs in the render loop.
  /// See vd_key.h.
  external VdChromaKey key;

  /// How this clip joins the one before it on the same track. A zeroed
  /// VdClipTransition is "a plain cut", so this is a field a caller can ignore.
  ///
  /// It belongs to the *incoming* clip and names only its own head, so there is
  /// one place a transition is written down and no way for the two sides of a
  /// cut to disagree about it. The engine finds the outgoing clip itself — the
  /// one on the same track whose end is exactly this clip's start — once per
  /// edit rather than once per frame. See vd_transition.h.
  external VdClipTransition transition;

  /// How it arrives and how it leaves. A zeroed VdClipAnim is "no animation",
  /// so this is another field a caller can ignore.
  ///
  /// Evaluated per frame and composed with `transform` rather than replacing
  /// it: a caption parked at the bottom that slides up slides up from below
  /// its own position. See vd_anim.h.
  external VdClipAnim anim;

  /// False for a clip that contributes only sound: one on an audio lane, or a
  /// file with no picture in it. The compositor skips it rather than opening a
  /// decoder that will never yield a frame and holding a cache slot with it.
  ///
  /// The caller is told to say, rather than the engine probing to find out,
  /// because the document already knows — and a music bed should not cost a
  /// file open on every edit to establish that it has no video.
  @ffi.Bool()
  external bool has_video;

  /// Linear gain on this clip's sound, 0 for silent. Mute is spelled 0 here:
  /// the document keeps the difference between "muted" and "turned down",
  /// because unmuting has to give the level back, but by the time it reaches
  /// the engine that distinction has been decided and only the number matters.
  @ffi.Float()
  external double gain;

  /// Ramps from silence over `fade_in` at the head and to silence over
  /// `fade_out` at the tail. Ticks, like every other length that crosses here.
  @VdTick()
  external int fade_in;

  @VdTick()
  external int fade_out;

  /// The shape both of those ramps take. Zero is linear, which is the shape
  /// every fade had before there was a choice — so an existing project sounds
  /// bit for bit as it did. See VdFadeCurve.
  @ffi.UnsignedInt()
  external int fade_curveAsInt;

  VdFadeCurve get fade_curve => VdFadeCurve.fromValue(fade_curveAsInt);

  /// What this clip sounds like: one of a short list of corrections and one
  /// effect, or VD_EQ_NONE for the clips nobody touched, which is almost all of
  /// them. A name rather than a set of bands, for the reason `look` is a name
  /// rather than a lattice — see vd_eq.h.
  @ffi.UnsignedInt()
  external int eqAsInt;

  VdEqPreset get eq => VdEqPreset.fromValue(eqAsInt);

  /// The volume line: gain over the source, sorted by `source_time`, and a
  /// multiplier on `gain` rather than a replacement for it. NULL and 0 mean a
  /// clip nobody has automated, which is almost all of them.
  ///
  /// The only thing on this struct that is not a scalar, because it is the only
  /// thing whose length the document decides. Copied on set_timeline, like
  /// `path`; the caller keeps ownership of its own array.
  external ffi.Pointer<VdVolumePoint> volume_points;

  @ffi.Int32()
  external int volume_point_count;
}

final class VdTimeline extends ffi.Struct {
  @ffi.Int32()
  external int width;

  @ffi.Int32()
  external int height;

  external VdRational frame_rate;

  external ffi.Pointer<VdTimelineClip> clips;

  @ffi.Int32()
  external int clip_count;
}

final class VdEngineOptions extends ffi.Struct {
  /// 0 to skip opening an output device. The audio path still decodes and
  /// mixes, and vd_engine_audio_renderer can still be pulled — which is how
  /// the tests exercise A/V sync without making a noise, and how a headless
  /// export will avoid touching the sound card.
  @ffi.Int32()
  external int audio_output;
}

/// What to draw instead of the frame the export would write.
///
/// A view mode is a property of the person looking, not of the document, which
/// is why it lives here beside the clock and the position — the only other two
/// things in this engine that are not the document — rather than on a clip.
/// Nothing in a project file can record one, because it never reaches one.
///
/// It is also what keeps "preview and export differ in the clock and in nothing
/// else" true rather than approximately true: the second difference is now
/// *named*, and vd_export builds its own headless VdEngine that never calls
/// this, so a zeroed engine renders exactly what the export writes.
///
/// Values cross the FFI boundary as integers: append only, never reorder.
enum VdViewMode {
  /// The frame the export would write. What a zeroed engine renders.
  VD_VIEW_NORMAL(0),

  /// Every layer's alpha as opaque luminance: white where it reaches the frame,
  /// black where it does not. The fastest way to see what a chroma key's
  /// tolerance is actually doing, and meaningless without one.
  VD_VIEW_MATTE(1),

  /// The picture as it came off the wire: no grade, no look and no key on any
  /// layer. This is what vd_engine_pick_color renders through, and the reason
  /// it has to — a colour picked out of a graded frame is a colour that moves
  /// the moment the grade does, and with a key already on there is no screen
  /// left to point at.
  VD_VIEW_PLAIN(2);

  final int value;
  const VdViewMode(this.value);

  static VdViewMode fromValue(int value) => switch (value) {
    0 => VD_VIEW_NORMAL,
    1 => VD_VIEW_MATTE,
    2 => VD_VIEW_PLAIN,
    _ => throw ArgumentError('Unknown value for VdViewMode: $value'),
  };
}

typedef VdFrameCallbackFunction = ffi.Void Function(
  ffi.Pointer<ffi.Void> context,
);
typedef DartVdFrameCallbackFunction = void Function(
  ffi.Pointer<ffi.Void> context,
);

/// Called from the render thread each time a new frame is published. The
/// plugin hooks this to -[FlutterTextureRegistry textureFrameAvailable:].
/// Must not block and must not call back into the engine.
typedef VdFrameCallback =
    ffi.Pointer<ffi.NativeFunction<VdFrameCallbackFunction>>;

final class VdEngineStats extends ffi.Struct {
  @ffi.Int64()
  external int frames_presented;

  /// Frames whose deadline had already passed when they were ready. This is
  /// the number that says whether playback is actually keeping up.
  @ffi.Int64()
  external int frames_late;

  @ffi.Double()
  external double composite_ms_avg;

  @ffi.Double()
  external double present_fps;

  @VdTick()
  external int position;

  @VdTick()
  external int duration;

  @ffi.Int32()
  external int state;

  @ffi.Int32()
  external int open_decoders;

  @ffi.Int32()
  external int active_layers;

  @ffi.Double()
  external double last_seek_ms;

  /// True when the timeline has audio, and therefore when the audio clock is
  /// the one driving playback.
  @ffi.Bool()
  external bool audio_available;

  /// Times the device asked for audio that had not been decoded yet. Unlike a
  /// late video frame, every one of these is audible.
  @ffi.Int64()
  external int audio_underruns;

  @ffi.Int32()
  external int audio_buffered_frames;

  /// Renders that happened because something asked for one rather than because
  /// the playhead reached a new frame. A seek is one; a steady stream of them
  /// during playback means something is spuriously repainting.
  @ffi.Int64()
  external int forced_renders;

  /// Times the playhead was seen to move backwards during playback. The audio
  /// clock and the wall clock do not tick at quite the same rate, so a position
  /// read that falls back from one to the other can dip — and a dip across a
  /// frame boundary would republish a frame that has already been shown.
  @ffi.Int64()
  external int clock_regressions;

  /// Captions laid out since the engine started. This is the number that says
  /// whether the raster cache is working: it should tick once per caption per
  /// edit that changed one, and never during playback. A steady stream of them
  /// means every frame is re-running Core Text, which is the whole thing the
  /// cache exists to prevent.
  @ffi.Int64()
  external int text_rasters;

  /// Shapes drawn, on the same terms and read the same way. A counter of its
  /// own rather than a shared "generated rasters", because the two answer
  /// different questions: a caption's raster is the expensive one and the one
  /// an animation can invalidate per character, and folding a shape's into it
  /// would blunt exactly the measurement text_rasters exists to make.
  @ffi.Int64()
  external int shape_rasters;

  /// Times a sticker put a *different* frame on screen. This is what says the
  /// retiming is happening: a 4 fps sticker on a 60 fps timeline should tick
  /// this four times a second, not sixty. A stream of them at the project's
  /// rate means every frame is being copied again to show the same picture.
  @ffi.Int64()
  external int sticker_frames;

  /// Look cubes uploaded to the GPU since the engine started. Straight from the
  /// compositor, and read the same way `text_rasters` is: a look is the same
  /// few hundred kilobytes on every frame of every clip wearing it, so this
  /// should tick once per look and never during playback or during a drag on
  /// the strength slider.
  @ffi.Int64()
  external int lut_uploads;

  /// Stickers decoded whole since the engine started, and what they are
  /// holding. An open is expensive and a byte is scarce, so both are worth
  /// watching: a count that climbs during playback means the cache is thrashing
  /// its budget, and the bytes are the budget it is thrashing.
  @ffi.Int64()
  external int sticker_opens;

  @ffi.Int64()
  external int sticker_bytes;
}

final class VdExport extends ffi.Opaque {}

/// What the picture is coded as.
///
/// Two, and only two, because they are the two answers to one question: H.264
/// plays everywhere and HEVC is half the size. Anything else is a preference
/// nobody in this product's audience has. The index crosses the FFI boundary as
/// an integer — see `ExportCodec` in the plugin — so append only.
enum VdExportCodec {
  VD_CODEC_H264(0),
  VD_CODEC_HEVC(1);

  final int value;
  const VdExportCodec(this.value);

  static VdExportCodec fromValue(int value) => switch (value) {
    0 => VD_CODEC_H264,
    1 => VD_CODEC_HEVC,
    _ => throw ArgumentError('Unknown value for VdExportCodec: $value'),
  };
}

final class VdExportSettings extends ffi.Struct {
  @ffi.UnsignedInt()
  external int codecAsInt;

  VdExportCodec get codec => VdExportCodec.fromValue(codecAsInt);

  /// Bits per second for the picture. 0 asks for vd_export_default_bitrate,
  /// which is what every preset uses — a number here is for somebody who knows
  /// they want one.
  @ffi.Int64()
  external int video_bitrate;

  /// Bits per second for the sound. 0 is 192 kbps, which is transparent enough
  /// for AAC-LC at 48 kHz stereo that nobody will hear the difference and small
  /// enough that nobody will notice the size.
  @ffi.Int32()
  external int audio_bitrate;

  /// False writes no audio track at all. A timeline with nothing that makes a
  /// sound gets no track either way — a silent AAC stream is not a courtesy.
  @ffi.Bool()
  external bool include_audio;
}

enum VdExportState {
  VD_EXPORT_RUNNING(0),
  VD_EXPORT_DONE(1),
  VD_EXPORT_CANCELLED(2),
  VD_EXPORT_FAILED(3);

  final int value;
  const VdExportState(this.value);

  static VdExportState fromValue(int value) => switch (value) {
    0 => VD_EXPORT_RUNNING,
    1 => VD_EXPORT_DONE,
    2 => VD_EXPORT_CANCELLED,
    3 => VD_EXPORT_FAILED,
    _ => throw ArgumentError('Unknown value for VdExportState: $value'),
  };
}

final class VdExportProgress extends ffi.Struct {
  /// VdExportState
  @ffi.Int32()
  external int state;

  @ffi.Int64()
  external int frames_written;

  @ffi.Int64()
  external int frames_total;

  /// Where on the timeline the last written frame was. The number a progress
  /// bar over a timeline wants, as opposed to the fraction `frames_written`
  /// gives.
  @VdTick()
  external int position;

  /// A negative VdResult once `state` is VD_EXPORT_FAILED, VD_OK otherwise.
  @ffi.Int32()
  external int error;

  @ffi.Double()
  external double elapsed_ms;
}

final class VdThumbnail extends ffi.Struct {
  @ffi.Int32()
  external int width;

  @ffi.Int32()
  external int height;

  /// Tightly packed BGRA, width * height * 4 bytes. Owned by the caller;
  /// release with vd_thumbnail_free.
  external ffi.Pointer<ffi.Uint8> pixels;
}

final class VdAudioSource extends ffi.Opaque {}

final class VdAudioRing extends ffi.Opaque {}

final class VdAudioStats extends ffi.Struct {
  @ffi.Int64()
  external int frames_rendered;

  /// Times the device asked for audio that had not been decoded yet. Any
  /// number above zero here is audible.
  @ffi.Int64()
  external int underruns;

  @ffi.Int32()
  external int buffered_frames;

  @ffi.Int32()
  external int open_sources;
}

final class VdAudioDevice extends ffi.Opaque {}

/// The pyramid. `buckets` holds every level concatenated finest-first, two
/// int16 per bucket — the minimum then the maximum sample in it, scaled by
/// 32767 and clamped to +/-32767.
///
/// Signed, and both ends kept, because sound is not symmetrical: a rectified
/// waveform drawn from absolute values looks tidier and hides which way a
/// transient went, and mirroring one half is a picture of a file nobody has.
final class VdPeaks extends ffi.Struct {
  @ffi.Int32()
  external int level_count;

  /// Level 0's bucket size, in audio frames. Level n's is this << n.
  @ffi.Int32()
  external int frames_per_bucket;

  @ffi.Int32()
  external int sample_rate;

  /// Channels the peaks were taken across. The minimum and maximum are over
  /// every sample of every channel in the bucket, not over a mono downmix:
  /// summing to mono lets two out-of-phase channels cancel into a flat line
  /// for audio that is plainly audible.
  @ffi.Int32()
  external int channels;

  /// Audio frames scanned, and the same length in ticks.
  @ffi.Int64()
  external int frame_count;

  @VdTick()
  external int duration;

  @ffi.Array.multi([16])
  external ffi.Array<ffi.Int32> bucket_counts;

  /// Sum of bucket_counts; `buckets` holds twice this many int16.
  @ffi.Int64()
  external int bucket_total;

  /// Owned by the caller; release with vd_peaks_free.
  external ffi.Pointer<ffi.Int16> buckets;
}

